import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// 模拟一个网络API，定期产生数据
fun networkDataStream(): Flow<String> = flow {
    println("数据源开始发射 (线程: ${Thread.currentThread().name})")
    repeat(5) { i ->
        delay(100) // 模拟网络延迟
        println("发射数据: $i")
        emit("Data-$i") // 发射数据
    }
}.flowOn(Dispatchers.IO) // 确保生产发生在IO线程

// 应用多种操作符的Flow管道
fun processedFlow(): Flow<String> {
    return networkDataStream()
        .map { data ->
            println("处理数据 (线程: ${Thread.currentThread().name}): $data")
            data.uppercase() // 模拟数据转换
        }
        .catch { e ->
            println("捕获到上游错误: ${e.message}")
            emit("FALLBACK_DATA") // 错误恢复
        }
        .onCompletion { cause ->
            if (cause == null) println("Flow正常完成")
            else println("Flow因异常完成: $cause")
        }
        .buffer(capacity = 2, onBufferOverflow = BufferOverflow.DROP_OLDEST) // 背压策略：缓冲区大小为2，满时丢弃最旧数据
}

fun main() = runBlocking {
    println("主协程开始 (线程: ${Thread.currentThread().name})")

    // 示例1：使用 collectLatest，新数据会取消旧数据的处理
    println("\n--- 示例1: collectLatest (快速变化场景) ---")
    val job1 = launch {
        processedFlow()
            .collectLatest { value ->
                println("CollectLatest 收到: $value，开始处理 (可能被中断)...")
                delay(200) // 模拟耗时处理
                println("CollectLatest 完成处理: $value")
            }
    }
    job1.join()

    // 示例2：使用通常的 collect，并应用 conflate 策略
    println("\n--- 示例2: collect + conflate (关注最新状态) ---")
    val job2 = launch {
        processedFlow()
            .conflate() // 如果生产者太快，消费者只处理最新的
            .collect { value ->
                println("Conflated Collect 收到: $value")
                delay(300) // 模拟更慢的消费者
                println("Conflated Collect 处理完: $value")
            }
    }
    job2.join()

    println("\n主协程结束")
}

